os.makedirs(jv + 'mani', exist_ok=True)
for name, b64 in FILES.items():
    text = base64.b64decode(b64).decode('utf-8')
    if name == 'ManiCore.kt':
        marker = 'const val PANEL_URL = "https://YOUR_PANEL_DOMAIN"'
        if marker not in text:
            raise SystemExit('PATCH FAILED: PANEL_URL marker missing')
        text = text.replace(marker, 'const val PANEL_URL = "%s"' % panel)
    open(jv + 'mani/' + name, 'w', encoding='utf-8').write(text)


def edit(path, pairs):
    s = open(path, encoding='utf-8').read()
    for a, b in pairs:
        if a not in s:
            raise SystemExit('PATCH FAILED (pattern missing) in %s: %s' % (path, a[:70]))
        s = s.replace(a, b, 1)
    open(path, 'w', encoding='utf-8').write(s)


edit(jv + 'ui/main/MainActivity.kt', [
    ('        MainScreen(\n            mainViewModel = mainViewModel,', '        com.v2ray.ang.mani.ManiRoot(\n            mainViewModel = mainViewModel,'),
    ('            onNavigate = { route -> navigateTo(route) },\n', ''),
])
for p in ['src/main/res/values/strings.xml', 'src/main/res/values-fa/strings.xml']:
    edit(app + p, [('<string name="app_name" translatable="false">v2rayNG</string>', '<string name="app_name" translatable="false">ManiRay</string>')])
edit(app + 'build.gradle.kts', [('applicationId = "com.v2ray.ang"', 'applicationId = "com.v2ray.ang.maniray"')])
print('ManiRay app patch applied. PANEL_URL =', panel)
